import{demo}from'./core.mjs';
export const PROFILES=[{id:'dairy',name:'Сосновый берег',type:'Молочная ферма',caption:'Сыр, молоко, творог. Скоропортящиеся партии и частые поставки.',initials:'СБ',color:'#327d76'}, {id:'garden',name:'Луговые овощи',type:'Овощное хозяйство',caption:'Томаты, огурцы, зелень. Объёмный урожай и сезонный спрос.',initials:'ЛО',color:'#a28e57'}, {id:'apiary',name:'Тихая пасека',type:'Пасека и травы',caption:'Мёд, чай и подарочные наборы. Длинное хранение, важны карточки.',initials:'ТП',color:'#bc8b65'}, {id:'bakery',name:'Хлебная поляна',type:'Фермерская пекарня',caption:'Хлеб и выпечка. Короткий срок, ежедневное планирование выпуска.',initials:'ХП',color:'#9b7eab'}];
export function demoProfile(id='dairy',scenario='balanced'){const d=demo(scenario),profile=PROFILES.find(p=>p.id===id)||PROFILES[0];d.profileId=profile.id;d.farm=profile.name;d.source='Демо: '+profile.type+', 28 дней';if(id==='dairy')return d;
 const names=id==='garden'?['Томаты розовые, 1 кг','Огурцы, 1 кг','Базилик, 50 г','Морковь, 1 кг','Салат, 150 г','Тыква, 1 кг','Картофель, 2 кг','Перец сладкий, 1 кг']:id==='apiary'?['Мёд липовый, 500 г','Мёд гречишный, 500 г','Мёд цветочный, 500 г','Иван-чай, 70 г','Чай с чабрецом, 50 г','Свеча из воска','Медовый набор, 3 банки','Соты, 200 г']:['Хлеб ржаной, 600 г','Багет, 250 г','Хлеб с семечками, 500 г','Булочка с корицей','Пирог с яблоком, 1 кг','Печенье овсяное, 200 г','Сухари, 150 г','Лепёшка, 200 г'];
 const prices=id==='garden'?[280,180,90,100,130,120,160,260]:id==='apiary'?[750,690,650,350,290,240,1850,480]:[220,140,270,110,890,190,120,100];
 const stocks=id==='garden'?[94,12,64,110,70,85,150,44]:id==='apiary'?[80,42,68,70,36,45,20,32]:[30,8,35,66,18,40,58,54];
 const expiry=id==='garden'?[3,5,2,20,2,60,30,7]:id==='apiary'?[240,240,240,180,180,1000,240,90]:[2,1,3,2,2,10,60,2];
 const multiplier=id==='garden'?1.7:id==='apiary'?.7:2.2;
 d.products=d.products.map((p,i)=>({...p,name:names[i],price:prices[i],cost:Math.round(prices[i]*(id==='apiary'?.48:.56)),stock:stocks[i],expiresIn:expiry[i],leadDays:id==='bakery'?1:p.leadDays,category:id==='garden'?(i===2||i===4?'Зелень':'Овощи'):id==='apiary'?(i===3||i===4?'Травы':i===5?'Изделия из воска':'Пасека'):(i===4?'Пироги':i===3||i===5?'Выпечка':'Хлеб'),symbol:names[i][0],unit:'уп'}));
 d.sales=d.sales.map(s=>{const index=d.products.findIndex(p=>p.id===s.productId),p=d.products[index],units=Math.max(0,Math.round(s.units*multiplier*(1+.15*Math.sin(index))));return{...s,units,views:Math.round(s.views*(id==='apiary'?1.3:1.15)),revenue:units*p.price};});
 d.segments=d.segments.map((s,i)=>({...s,count:Math.round(s.count*(id==='bakery'?1.8:id==='garden'?1.3:.7)),consented:Math.round(s.consented*(id==='bakery'?1.8:id==='garden'?1.3:.7)),avgCheck:Math.round(s.avgCheck*(id==='apiary'?1.4:id==='bakery'?.7:.9))}));return d;
}
